// KYA-OS story F-2: fixtures/verifier/*.json are generated by scripts/gen-fixtures.ts with the
// JavaScript reference verifier (@helixid/sdk-js) and checked in. This re-derives every file
// from current source and fails when the checked-in copy drifts.
import { readFileSync, readdirSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { buildVerifierFixtures, requestProofFile } from '../../../scripts/gen-fixtures.js';

const dir = new URL('../../../fixtures/verifier/', import.meta.url);

describe('fixtures/verifier', () => {
  it('is exactly what scripts/gen-fixtures.ts generates now', async () => {
    const { environment, files } = await buildVerifierFixtures();
    expect(readFileSync(new URL('environment.json', dir), 'utf8')).toBe(`${JSON.stringify(environment, null, 2)}\n`);
    for (const [name, cases] of Object.entries(files)) {
      expect(readFileSync(new URL(`${name}.json`, dir), 'utf8'), name).toBe(`${JSON.stringify({ generated_from: environment.generated_from, cases }, null, 2)}\n`);
    }
    expect(readdirSync(dir).filter((name) => name.endsWith('.json')).sort()).toEqual(['chain.json', 'environment.json', 'proof.json', 'seams.json', 'status.json', 'valid.json']);
  }, 60_000);

  // Story C-C: the §11.2 order, the carrier keys and chains without a proof, beside the F-2 set.
  it('writes fixtures/kya-os-helix/request-proof.json exactly as generated now', async () => {
    const { environment, requestProof } = await buildVerifierFixtures();
    expect(readFileSync(new URL('../../../fixtures/kya-os-helix/request-proof.json', import.meta.url), 'utf8')).toBe(requestProofFile(environment, requestProof));
    const byName = new Map(requestProof.map((fixture) => [fixture.name, fixture.expected]));
    expect(byName.get('order_nonce_before_signature')!.reasons).toEqual(['nonce_replayed']);
    expect(byName.get('order_key_before_audience')!.reasons).toEqual(['kid_not_in_did_document']);
    expect(byName.get('legacy_key')).toMatchObject({ ok: true, proofFloor: true });
    expect(byName.get('canonical_key_wins_when_broken')!.reasons).toEqual(['malformed_proof']);
    expect(byName.get('chain_without_proof_required')!.reasons).toEqual(['proof_missing']);
    expect(byName.get('chain_without_proof_l2')).toMatchObject({ ok: true, level: 'L2', proofFloor: false });
    expect(byName.get('cnf_unfused_l3_minus')).toMatchObject({ ok: true, level: 'L3', proofAssurance: 'L3-minus', warnings: ['cnf_present_but_token_unfused'] });
  }, 60_000);

  it('covers every failure family the story names', async () => {
    const { files } = await buildVerifierFixtures();
    const codes = new Set(Object.values(files).flatMap((cases) => cases.flatMap((fixture) => fixture.expected.reasons)));
    for (const code of [
      'attenuation_violation',
      'status_revoked',
      'status_stale',
      'nonce_replayed',
      'invalid_signature',
      'hop_proof_invalid',
      'nonce_seam_missing',
      'did_membership_unverifiable',
      'chain_too_long',
      'audience_mismatch',
      'kid_did_mismatch',
      'request_hash_mismatch',
      'root_not_responsible_party',
      'leaf_invoker_mismatch',
      'issuer_untrusted',
    ]) {
      expect(codes, code).toContain(code);
    }
    expect(files['valid']!.find((fixture) => fixture.name === 'legacy_proof_profile')!.expected.ok).toBe(true);
  }, 60_000);
});
